"""Exact money parsing, summation and formatting (R10)."""
import re
from decimal import (
    Context, Decimal, Inexact, InvalidOperation, Overflow, ROUND_HALF_UP,
)

AMOUNT_RE = re.compile(r"-?[0-9]+(\.[0-9]+)?")

# Summation context: exact (Inexact trapped), effectively unlimited precision.
MONEY_CONTEXT = Context(
    prec=10**6, rounding=ROUND_HALF_UP,
    traps=[InvalidOperation, Inexact, Overflow],
)

# Display context: rounding is intentionally inexact, so Inexact is not trapped.
_FORMAT_CONTEXT = Context(
    prec=10**6, rounding=ROUND_HALF_UP, traps=[InvalidOperation, Overflow],
)

_CENT = Decimal("0.01")


def parse_amount(text):
    """Return Decimal for a valid amount string (after str.strip()), else None."""
    text = text.strip()
    if AMOUNT_RE.fullmatch(text) is None:
        return None
    return Decimal(text)


def money_sum(values, start=Decimal(0)):
    """Sum Decimals exactly under MONEY_CONTEXT (T6 should use this)."""
    total = start
    for v in values:
        total = MONEY_CONTEXT.add(total, v)
    return total


def format_money(value):
    """Round once to 2 dp, ROUND_HALF_UP; never returns '-0.00'."""
    q = value.quantize(_CENT, rounding=ROUND_HALF_UP, context=_FORMAT_CONTEXT)
    if q == 0:
        return "0.00"
    return format(q, "f")
import csv
import io

from .errors import LedgerError


def read_table(path, required, exit_code):
    def fail(msg):
        raise LedgerError(msg, exit_code)

    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        fail(f"{path}: cannot read file")
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        fail(f"{path}: not valid UTF-8")
    if not text:
        fail(f"{path}: missing header")

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        raw = next(reader)
    except csv.Error:
        fail(f"{path}:{reader.line_num}: malformed CSV")
    header = [h.strip().lower() for h in raw]
    index = {}
    for i, name in enumerate(header):
        if name in index:
            fail(f"{path}: duplicate column '{name}'")
        index[name] = i
    for name in required:
        if name not in index:
            fail(f"{path}: missing column '{name}'")

    rows = []
    while True:
        try:
            fields = next(reader)
        except StopIteration:
            break
        except csv.Error:
            fail(f"{path}:{reader.line_num}: malformed CSV")
        line = reader.line_num
        if not fields:
            continue
        if len(fields) != len(header):
            fail(f"{path}:{line}: expected {len(header)} fields, got {len(fields)}")
        rows.append((line, fields))
    return index, rows

