import re
from dataclasses import dataclass
from datetime import date as _date
from decimal import Decimal

from .csvio import read_table
from .errors import EXIT_TX, LedgerError
from .money import parse_amount

DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


@dataclass(frozen=True)
class Transaction:
    date: str
    description: str
    amount: Decimal


def _valid_date(text):
    if DATE_RE.fullmatch(text) is None:
        return False
    try:
        _date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return False
    return True


def load_transactions(path):
    index, rows = read_table(path, ["date", "description", "amount"], EXIT_TX)
    di, si, ai = index["date"], index["description"], index["amount"]
    out = []
    for line, fields in rows:
        d = fields[di].strip()
        if not _valid_date(d):
            raise LedgerError(f"{path}:{line}: invalid date '{d}'", EXIT_TX)
        a = fields[ai].strip()
        amount = parse_amount(a)
        if amount is None:
            raise LedgerError(f"{path}:{line}: invalid amount '{a}'", EXIT_TX)
        out.append(Transaction(d, fields[si].strip(), amount))
    return out
def dedup(transactions):
    seen = set()
    kept = []
    for t in transactions:
        key = (t.date, t.description, t.amount)
        if key in seen:
            continue
        seen.add(key)
        kept.append(t)
    return kept, len(transactions) - len(kept)
import re
from dataclasses import dataclass

from .csvio import read_table
from .errors import EXIT_RULES, LedgerError


@dataclass(frozen=True)
class Rule:
    category: str
    type: str
    pattern: str
    priority: int
    compiled: object = None


def load_rules(path):
    index, rows = read_table(path, ["category", "type", "pattern", "priority"], EXIT_RULES)
    rules = []
    for line, fields in rows:
        def get(name):
            return fields[index[name]].strip()

        def fail(msg):
            raise LedgerError(f"{path}:{line}: {msg}", EXIT_RULES)

        category, typ, pattern, prio = get("category"), get("type"), get("pattern"), get("priority")
        if not category:
            fail("empty category")
        if typ not in ("contains", "regex"):
            fail(f"invalid type '{typ}'")
        if not pattern:
            fail("empty pattern")
        if not re.fullmatch(r"-?[0-9]+", prio, re.ASCII):
            fail(f"invalid priority '{prio}'")
        compiled = None
        if typ == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except re.error:
                fail(f"invalid regex '{pattern}'")
        rules.append(Rule(category, typ, pattern, int(prio), compiled))
    return rules


def categorize(description, rules):
    best = None
    folded = description.casefold()
    for r in rules:
        if best is not None and r.priority <= best.priority:
            continue
        if r.type == "contains":
            hit = r.pattern.casefold() in folded
        else:
            hit = r.compiled.search(description) is not None
        if hit:
            best = r
    return best.category if best else "Uncategorized"

